import React, { useState, useEffect } from 'react';
// Session 1 (SYNC-PLAN.md): auth only, nothing syncs. This import is the line
// that ends artifact preview for this file - accepted, and the price of every
// session from here on. The app must remain FULLY functional signed out; no
// feature is gated behind authUser, ever.
import {
  auth,
  db,
  startGoogleSignIn,
  endSignIn,
  onAuthStateChanged,
  getRedirectResult,
  describeAuthError,
  pushDocs,
  onSnapshot,
  collection,
  doc
} from './firebase.js';


// ---- Inline date picker ----------------------------------------------------
// Deliberately not <input type="date">. The native picker renders as a browser
// overlay attached to a specific DOM node, and this app re-creates task rows on
// parent renders - when that node is replaced mid-interaction, iOS commits the
// highlighted value (today) as it tears the sheet down. A React-rendered
// calendar has no overlay to lose: worst case it simply closes, and it can
// never write a date the user didn't tap.
function InlineDatePicker({ value, onChange, style, onOpenChange }) {
  const [open, setOpen] = React.useState(false);
  const rootRef = React.useRef(null);
  const popupRef = React.useRef(null);

  // Where the calendar hangs relative to its trigger. It opens downward by
  // default, which is wrong for a date field near the bottom of a scrolling
  // modal - the popup lands past the modal's edge and is clipped, so you get
  // a sliver of calendar and no way to reach the days.
  //
  // Two things fix it together, because neither is enough alone: flip above
  // the trigger when there is more room up there, and then scroll whatever is
  // actually scrolling until the whole popup is on screen. Flipping alone
  // fails when there is not enough room in either direction; scrolling alone
  // fails when the popup would have to sit below the end of the content.
  const [placement, setPlacement] = React.useState('below');

  // The card above needs to know a popup is open inside it, so the tap that
  // dismisses this calendar isn't also read as a tap on the card.
  React.useEffect(() => {
    if (onOpenChange) onOpenChange(open);
  }, [open, onOpenChange]);

  // Placement is decided before paint so the calendar never appears in one
  // spot and jumps to another.
  React.useLayoutEffect(() => {
    if (!open) { setPlacement('below'); return; }
    const trigger = rootRef.current;
    const popup = popupRef.current;
    if (!trigger || !popup) return;
    const t = trigger.getBoundingClientRect();
    const popupH = popup.offsetHeight;
    const GAP = 12;
    const roomBelow = window.innerHeight - t.bottom;
    const roomAbove = t.top;
    // Only flip when below genuinely doesn't fit AND above does. A flip that
    // trades one clipped edge for another just moves the problem.
    if (roomBelow < popupH + GAP && roomAbove > popupH + GAP) {
      setPlacement('above');
    } else {
      setPlacement('below');
    }
  }, [open]);

  // Then scroll it fully into view. block:'nearest' moves the nearest
  // scrollable ancestor by the smallest amount that reveals the element, so a
  // picker that is already visible doesn't get yanked around.
  React.useEffect(() => {
    if (!open) return;
    const id = requestAnimationFrame(() => {
      const popup = popupRef.current;
      if (!popup || !popup.scrollIntoView) return;
      try {
        popup.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' });
      } catch {
        // Older Safari rejects the options object rather than ignoring it.
        popup.scrollIntoView(false);
      }
    });
    return () => cancelAnimationFrame(id);
  }, [open, placement]);

  // There was no outside-tap close at all: the only ways out were the Close
  // button and picking a date. Tapping anywhere else went straight through to
  // the card, which collapsed the task and took the open calendar with it.
  React.useEffect(() => {
    if (!open) return;
    const onDown = (e) => {
      if (rootRef.current && !rootRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('touchstart', onDown);
    return () => {
      document.removeEventListener('mousedown', onDown);
      document.removeEventListener('touchstart', onDown);
    };
  }, [open]);
  const parse = (v) => {
    if (!v) return null;
    const [y, m, d] = String(v).split('-').map(Number);
    return (y && m && d) ? new Date(y, m - 1, d) : null;
  };
  const selected = parse(value);
  const [view, setView] = React.useState(() => {
    const base = selected || new Date();
    return { year: base.getFullYear(), month: base.getMonth() };
  });

  const MONTHS = ['January','February','March','April','May','June',
                  'July','August','September','October','November','December'];
  const pad = (n) => String(n).padStart(2, '0');
  const toValue = (y, m, d) => `${y}-${pad(m + 1)}-${pad(d)}`;

  const daysInMonth = new Date(view.year, view.month + 1, 0).getDate();
  const firstWeekday = new Date(view.year, view.month, 1).getDay();
  const today = new Date();
  const isToday = (d) => today.getFullYear() === view.year &&
    today.getMonth() === view.month && today.getDate() === d;
  const isSelected = (d) => selected && selected.getFullYear() === view.year &&
    selected.getMonth() === view.month && selected.getDate() === d;

  const shiftMonth = (delta) => setView(v => {
    const nm = v.month + delta;
    return { year: v.year + Math.floor(nm / 12), month: ((nm % 12) + 12) % 12 };
  });

  const stop = (e) => { e.stopPropagation(); };
  // The app has a global `button` rule: accent gradient, uppercase text,
  // letter-spacing, an accent-coloured glow and a lift on hover. Every control
  // in this picker is a plain field or a bare text button, so each one starts
  // from this reset. `transform` is pinned here because the global :hover rule
  // lifts buttons - a pseudo-class can't beat an inline style, so this is what
  // holds the field still.
  const btnReset = {
    boxShadow: 'none',
    textTransform: 'none',
    letterSpacing: 'normal',
    fontWeight: 500,
    transform: 'none'
  };
  // 44px is the iOS minimum comfortable touch target. These controls were
  // roughly 20px tall, which is a real miss on a phone-first app. Centring the
  // glyph keeps them looking the same size as before.
  const tapTarget = {
    minWidth: '44px', minHeight: '44px', padding: 0,
    display: 'inline-flex', alignItems: 'center', justifyContent: 'center'
  };
  // Matched to .project-selector and the app's text inputs so this sits in a
  // row with them without looking like a different kind of control.
  const field = {
    ...btnReset,
    padding: '10px 12px', background: 'rgba(var(--surface-rgb), 0.8)',
    backdropFilter: 'blur(4px)',
    border: '2px solid rgba(var(--accent-rgb), 0.2)', borderRadius: '20px',
    // No shadow. Inside an outlined panel a lifted control reads as floating
    // above the box that contains it; the border already separates it.
    boxShadow: 'none',
    color: value ? 'var(--text)' : '#8a8a9a', fontFamily: "'Nunito', sans-serif",
    fontSize: '0.95rem', cursor: 'pointer', minWidth: '132px', textAlign: 'left',
    // When a caller sizes the wrapper (width, flex, etc), the button should
    // fill it rather than sitting at its natural content width inside it.
    ...(style ? { width: '100%' } : {})
  };

  return (
    <span ref={rootRef} style={{
      position: 'relative',
      // inline-flex, not inline-block. The clear button is a sibling of the
      // trigger, and as inline content it wrapped onto a second line once the
      // field got narrow - which made a filled date field taller than an empty
      // one and knocked Start and End out of alignment with each other.
      display: 'inline-flex',
      alignItems: 'center',
      gap: '2px',
      whiteSpace: 'nowrap',
      verticalAlign: 'middle',
      ...style
    }}
      onMouseDown={stop} onTouchStart={stop} onClick={stop}>
      <button type="button" style={field} onClick={(e) => { stop(e); setOpen(o => !o); }}>
        {selected ? selected.toLocaleDateString('en-US',
          { month: 'short', day: 'numeric', year: 'numeric' })
          /* No placeholder text - an unset field reads as empty, like the
             other inputs. The non-breaking space keeps the button from
             collapsing to zero height when there's nothing to show. */
          : '\u00A0'}
      </button>
      {value && (
        <button type="button" title="Clear date" aria-label="Clear date"
          onClick={(e) => { stop(e); onChange(''); setOpen(false); }}
          style={{ ...btnReset, background: 'transparent', border: 'none',
            // Was a hardcoded grey - the last one in this component, so it
            // stayed cool-toned against the warm light theme.
            color: 'var(--text-muted)',
            cursor: 'pointer', fontSize: '1rem', flexShrink: 0, ...tapTarget }}>×</button>
      )}

      {open && (
        <div ref={popupRef} style={{
          position: 'absolute', left: 0, zIndex: 2000,
          ...(placement === 'above'
            ? { bottom: 'calc(100% + 6px)' }
            : { top: 'calc(100% + 6px)' }),
          background: 'rgba(var(--surface-deep-rgb), 0.99)',
          border: '2px solid rgba(var(--accent-rgb), 0.4)',
          borderRadius: '12px', padding: '12px', width: '252px',
          boxShadow: '0 10px 30px rgba(var(--shadow-rgb),0.55)',
          fontFamily: 'var(--font-ui)'
        }}>
          <div style={{ display: 'flex', alignItems: 'center',
            justifyContent: 'space-between', marginBottom: '8px' }}>
            <button type="button" aria-label="Previous month"
              onClick={(e) => { stop(e); shiftMonth(-1); }}
              style={{ ...btnReset, background: 'transparent', border: 'none', color: 'var(--text)',
                cursor: 'pointer', fontSize: '1.1rem', ...tapTarget }}>‹</button>
            <span style={{ color: 'var(--text)', fontSize: '0.85rem', fontWeight: 600 }}>
              {MONTHS[view.month]} {view.year}
            </span>
            <button type="button" aria-label="Next month"
              onClick={(e) => { stop(e); shiftMonth(1); }}
              style={{ ...btnReset, background: 'transparent', border: 'none', color: 'var(--text)',
                cursor: 'pointer', fontSize: '1.1rem', ...tapTarget }}>›</button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '2px' }}>
            {['S','M','T','W','T','F','S'].map((d, i) => (
              <div key={i} style={{ textAlign: 'center', color: '#8a8a9a',
                fontSize: '0.65rem', padding: '3px 0' }}>{d}</div>
            ))}
            {Array.from({ length: firstWeekday }).map((_, i) => <div key={'b' + i} />)}
            {Array.from({ length: daysInMonth }).map((_, i) => {
              const d = i + 1;
              const sel = isSelected(d);
              return (
                <button key={d} type="button"
                  onClick={(e) => { stop(e); onChange(toValue(view.year, view.month, d)); setOpen(false); }}
                  style={{
                    ...btnReset,
                    padding: '6px 0', borderRadius: '7px', cursor: 'pointer',
                    fontSize: '0.8rem', fontFamily: 'var(--font-ui)',
                    border: isToday(d) && !sel ? '1px solid rgba(var(--accent-rgb), 0.6)' : '1px solid transparent',
                    background: sel ? 'linear-gradient(135deg, var(--accent), var(--accent-light))' : 'transparent',
                    color: sel ? '#fff' : 'var(--text)', fontWeight: sel ? 700 : 500
                  }}>
                  {d}
                </button>
              );
            })}
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '10px' }}>
            <button type="button" onClick={(e) => {
                stop(e);
                const t = new Date();
                onChange(toValue(t.getFullYear(), t.getMonth(), t.getDate()));
                setOpen(false);
              }}
              style={{ ...btnReset, background: 'transparent', border: 'none', color: 'var(--accent-light)',
                cursor: 'pointer', fontSize: '0.78rem', fontFamily: 'var(--font-ui)' }}>
              Today
            </button>
            <button type="button" onClick={(e) => { stop(e); setOpen(false); }}
              style={{ ...btnReset, background: 'transparent', border: 'none', color: '#8a8a9a',
                cursor: 'pointer', fontSize: '0.78rem', fontFamily: 'var(--font-ui)' }}>
              Close
            </button>
          </div>
        </div>
      )}
    </span>
  );
}

// Monochrome calendar glyph, drawn deliberately without a date number. It
// replaces the 📅 emoji, which most platforms render with a fixed date baked
// into the artwork (July 17 on iOS) - sitting immediately before a real due
// date, that reads as a second, contradictory date. Stroked with currentColor
// so it inherits whatever the surrounding text is doing, including turning red
// alongside overdue dates.
function CalendarIcon({ size = 13 }) {
  return (
    <svg
      width={size} height={size} viewBox="0 0 16 16"
      fill="none" stroke="currentColor" strokeWidth="1.5"
      strokeLinecap="round" strokeLinejoin="round"
      aria-hidden="true"
      style={{ verticalAlign: '-1px', flexShrink: 0 }}
    >
      <rect x="2" y="3.5" width="12" height="10.5" rx="2" />
      <path d="M2 7.25h12" />
      <path d="M5.5 2v3" />
      <path d="M10.5 2v3" />
    </svg>
  );
}

// Companions to CalendarIcon, for the same reason: emoji are full-colour, vary
// by platform, and sit oddly beside the app's flat cream-on-navy palette. All
// stroke with currentColor so they inherit their surrounding text.
function IconBase({ size = 13, children }) {
  return (
    <svg
      width={size} height={size} viewBox="0 0 16 16"
      fill="none" stroke="currentColor" strokeWidth="1.5"
      strokeLinecap="round" strokeLinejoin="round"
      aria-hidden="true"
      style={{ verticalAlign: '-1px', flexShrink: 0 }}
    >
      {children}
    </svg>
  );
}

// Replaces 📦 on archived items.
function ArchiveIcon(props) {
  return (
    <IconBase {...props}>
      <rect x="1.75" y="2.25" width="12.5" height="3.5" rx="1" />
      <path d="M3 5.75v7a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1v-7" />
      <path d="M6.5 8.5h3" />
    </IconBase>
  );
}

// Replaces 🏗️ on project rows.
function ProjectIcon(props) {
  return (
    <IconBase {...props}>
      <path d="M8 1.75 14.25 5 8 8.25 1.75 5 8 1.75Z" />
      <path d="M1.75 8 8 11.25 14.25 8" />
      <path d="M1.75 11 8 14.25 14.25 11" />
    </IconBase>
  );
}

// Replaces 📷 on notes carrying images.
function ImageIcon(props) {
  return (
    <IconBase {...props}>
      <rect x="1.75" y="3" width="12.5" height="10" rx="2" />
      <circle cx="5.75" cy="6.5" r="1.15" />
      <path d="M2.25 11.5 5.75 8.5l3 2.5 2.25-1.75 2.75 2.25" />
    </IconBase>
  );
}

// Replaces ☑ on the details toolbar. U+2611 gets emoji presentation on iOS,
// so it rendered as a coloured glyph next to two plain text buttons.
function CheckboxIcon(props) {
  return (
    <IconBase {...props}>
      <rect x="2" y="2" width="12" height="12" rx="2.5" />
      <path d="M5 8.25 7.25 10.5 11 6.25" />
    </IconBase>
  );
}

// Replaces 🔥 as a priority marker. Filled rather than stroked, and kept in the
// app's existing priority orange - the colour is the signal here, so unlike the
// others this one doesn't inherit currentColor.
function FlameIcon({ size = 13 }) {
  return (
    <svg
      width={size} height={size} viewBox="0 0 16 16"
      aria-hidden="true"
      style={{ verticalAlign: '-2px', flexShrink: 0 }}
    >
      <path
        d="M8 1.5c.4 2-1 3-2.2 4.3C4.5 7.1 3.75 8.4 3.75 10a4.25 4.25 0 0 0 8.5 0c0-2.1-1.1-3.4-2.3-4.8-.6-.7-1.1-1.4-1.2-2.2-.3.5-.7.9-1.1 1.3.2-1 .3-1.9.35-2.8Z"
        fill="#FF8C42"
      />
      <path
        d="M8 8c.3 1-.5 1.6-1 2.2-.35.4-.5.8-.5 1.3a1.75 1.75 0 0 0 3.5 0c0-.9-.5-1.5-1-2.1-.4-.5-.8-.9-1-1.4Z"
        fill="#FFD93D"
      />
    </svg>
  );
}

// Collision-resistant IDs for tasks. Date.now() has millisecond resolution, so
// two tasks created in the same millisecond shared an ID. On one device that's
// unlikely; on a list shared between two people - both adding items while
// looking at the same fridge - it stops being unlikely, and a duplicate ID in a
// synced list means one person's edits land on the other's task.
// randomUUID needs a secure context, which localhost and any https host are;
// the fallback covers plain-http origins where it isn't exposed.
// Bullet list and Next Steps, so every details-toolbar button has an icon to
// fall back on when the labels are hidden on a narrow screen.
function BulletsIcon(props) {
  return (
    <IconBase {...props}>
      <circle cx="3" cy="4" r="1.1" fill="currentColor" stroke="none" />
      <circle cx="3" cy="8" r="1.1" fill="currentColor" stroke="none" />
      <circle cx="3" cy="12" r="1.1" fill="currentColor" stroke="none" />
      <path d="M6.5 4h7.5" />
      <path d="M6.5 8h7.5" />
      <path d="M6.5 12h7.5" />
    </IconBase>
  );
}


// A flag: the section marks something to come back to.
function FollowUpIcon(props) {
  return (
    <IconBase {...props}>
      <path d="M3.5 14.5V2" />
      <path d="M3.5 2.75h8.5l-2 2.75 2 2.75H3.5z" />
    </IconBase>
  );
}

// Indent / outdent for the details toolbar. Lines plus an arrow, matching the
// stroke weight of their neighbours. currentColor throughout, so they inherit
// the toolbar button's text colour in both themes and when active.
// The "where am I" arrow - the filled triangle Maps uses for a heading, rather
// than a crosshair. A crosshair reads as "aim at a point on the map"; this is a
// device reporting where it already is.
//
// Drawn on the same 16x16 grid as the toolbar icons so it sits at their weight.
// Slightly asymmetric on purpose: the notch in the base is what stops it
// reading as a paper plane.
function LocationArrowIcon(props) {
  return (
    <IconBase {...props}>
      <path
        d="M14 2L2 7.2l5.1 1.7L8.8 14z"
        fill="currentColor"
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinejoin="round"
      />
    </IconBase>
  );
}

function IndentIcon(props) {
  return (
    <IconBase {...props}>
      <path d="M2 3h12" />
      <path d="M7 6.5h7" />
      <path d="M7 9.5h7" />
      <path d="M2 13h12" />
      <path d="M2 6.5l2.5 1.75L2 10z" fill="currentColor" stroke="none" />
    </IconBase>
  );
}

function OutdentIcon(props) {
  return (
    <IconBase {...props}>
      <path d="M2 3h12" />
      <path d="M7 6.5h7" />
      <path d="M7 9.5h7" />
      <path d="M2 13h12" />
      <path d="M4.5 6.5L2 8.25 4.5 10z" fill="currentColor" stroke="none" />
    </IconBase>
  );
}

function makeId() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'id-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
}

// --- Rich text sanitising ---------------------------------------------------
// Task details and note bodies are stored as HTML and rendered with
// dangerouslySetInnerHTML. On a single device the only person who can put a
// <script> in your own notes is you. The moment a list is shared that stops
// being true: whatever your partner types is rendered inside your session, with
// reach over everything in localStorage. So the HTML is filtered on the way in
// and on the way out.
//
// The allowlist is small because the editors only ever produce a handful of
// tags: contenteditable divs and spans, <br>, bold from execCommand, bullet
// lists, and the checkbox inputs.
const RICH_TEXT_TAGS = new Set([
  'DIV', 'SPAN', 'P', 'BR', 'B', 'STRONG', 'I', 'EM', 'U', 'UL', 'OL', 'LI', 'INPUT', 'A'
]);
// Classes carry real behaviour and styling here, so a few are kept - but only
// these, so nothing can borrow the app's own styling to fake UI.
const RICH_TEXT_CLASSES = new Set([
  'task-checkbox', 'checkbox-line', 'follow-up-heading', 'task-link',
  // Mark a checkbox that has indented children beneath it, and the item that
  // closes such a group. Task details recompute these on load, so their absence
  // went unnoticed there - but a note is rendered straight from stored HTML with
  // nothing to recompute, so the hierarchy was flattened every time one saved.
  'has-children', 'ends-list'
]);

// Link targets are rebuilt, never passed through. Parsing with the URL
// constructor rather than pattern-matching matters: "javascript:" can be
// smuggled past a regex using embedded newlines, tabs, control characters or
// HTML entities, but none of that survives being parsed and re-serialised.
// Anything that isn't a plain web or mail address comes back null.
const SAFE_LINK_PROTOCOLS = new Set(['http:', 'https:', 'mailto:']);
function safeHref(value) {
  if (!value || typeof value !== 'string') return null;
  try {
    const base = (typeof window !== 'undefined' && window.location)
      ? window.location.href
      : 'https://localhost/';
    const url = new URL(value, base);
    return SAFE_LINK_PROTOCOLS.has(url.protocol) ? url.href : null;
  } catch (err) {
    return null;
  }
}

function sanitizeRichText(html) {
  if (!html || typeof html !== 'string') return '';
  if (typeof document === 'undefined') return '';

  // createHTMLDocument gives an inert document: parsing happens, but images
  // don't fetch and nothing executes. Assigning to a live element's innerHTML
  // would fire <img onerror> before we ever got to strip it.
  const doc = document.implementation.createHTMLDocument('');
  doc.body.innerHTML = html;

  const walk = (parent) => {
    // Static copy: the loop removes and unwraps as it goes.
    Array.from(parent.childNodes).forEach(node => {
      if (node.nodeType === 3) return;              // text is always fine
      if (node.nodeType !== 1) { node.remove(); return; }  // comments, etc

      const tag = node.tagName;

      if (!RICH_TEXT_TAGS.has(tag)) {
        // Unknown tags are unwrapped rather than deleted, so a paste wrapped in
        // some foreign element keeps its text. script and style are the
        // exception - there, the text content is the payload.
        if (tag === 'SCRIPT' || tag === 'STYLE') {
          node.remove();
        } else {
          // Clean the subtree BEFORE promoting it. This loop iterates a
          // snapshot of the children taken on entry, so anything moved up here
          // would otherwise never be visited - and a payload one level inside a
          // disallowed wrapper (<form><img onerror=...></form>) would ride
          // straight through untouched.
          walk(node);
          while (node.firstChild) parent.insertBefore(node.firstChild, node);
          node.remove();
        }
        return;
      }

      // The only input the editors make is a checkbox. Anything else claiming
      // to be an input is not ours.
      if (tag === 'INPUT' && node.getAttribute('type') !== 'checkbox') {
        node.remove();
        return;
      }

      Array.from(node.attributes).forEach(attr => {
        const name = attr.name.toLowerCase();
        if (name === 'class') {
          const kept = attr.value.split(/\s+/).filter(c => RICH_TEXT_CLASSES.has(c));
          if (kept.length) node.setAttribute('class', kept.join(' '));
          else node.removeAttribute('class');
          return;
        }
        if (tag === 'INPUT' && (name === 'type' || name === 'checked')) return;
        if (tag === 'A' && name === 'href') {
          const safe = safeHref(attr.value);
          if (safe) node.setAttribute('href', safe);
          else node.removeAttribute('href');
          return;
        }
        // The title is the full URL, shown on hover - plain text, and useful
        // because the visible label is just "Link".
        if (tag === 'A' && name === 'title') return;
        // Nested checklists carry their indent as an inline margin-left, so a
        // blanket style strip silently flattened them on every save. Rather
        // than allow style through, the value is rebuilt from scratch: parse
        // one number out, discard the original string, emit a known-good
        // declaration. Nothing an attacker writes can survive that, because
        // nothing of theirs is copied - only a matched integer.
        if (name === 'style') {
          const indent = /(?:^|;)\s*margin-left\s*:\s*(\d{1,3})px\s*(?:;|$)/i.exec(attr.value);
          if (indent) node.setAttribute('style', 'margin-left: ' + indent[1] + 'px');
          else node.removeAttribute('style');
          return;
        }
        // Everything else goes: on* handlers, src, href, srcset,
        // contenteditable, data-*. Nothing in the allowlist needs them, and an
        // attribute allowlist can't be outflanked the way a blocklist can.
        node.removeAttribute(attr.name);
      });

      if (tag === 'A') {
        if (!node.getAttribute('href')) {
          // The href didn't survive validation, so this is no longer a link.
          // Unwrap rather than keep a dead anchor that still looks clickable.
          const parent = node.parentNode;
          while (node.firstChild) parent.insertBefore(node.firstChild, node);
          parent.removeChild(node);
          return;
        }
        // Set here rather than trusted from the input: a link that opens in
        // this tab would navigate away from the app and lose unsaved edits,
        // and without noopener the opened page can reach back via window.opener.
        node.setAttribute('target', '_blank');
        node.setAttribute('rel', 'noopener noreferrer');
      }

      walk(node);
    });
  };

  walk(doc.body);
  return doc.body.innerHTML;
}

// ---- AI credentials --------------------------------------------------------
// The key lives in its own storage entry, NOT in the settings blob.
//
// That is not tidiness. buildBackup() puts `settings` into every exported
// backup file, and the error boundary's raw dump reads the same key - so a key
// stored there would be written into a JSON file the user is likely to email
// to themselves or drop in cloud storage, and into a crash dump they might
// paste into a bug report. Keeping it separate means "export a backup" can
// never mean "export my API key".
//
// It is also never sent anywhere except Anthropic's own endpoint, and it is
// deliberately not part of anything that will sync: a key belongs to a device
// and a person, not to a household.
const AI_KEY_STORAGE = 'little_fires_ai_key';
// First-run intro. Two separate keys on purpose.
//
// INTRO_DISMISSED_STORAGE is a per-device preference, like the AI key - it is
// deliberately NOT in `settings`, because settings are serialised into every
// exported backup, and importing someone else's backup should not tell your
// app whether you have seen an intro.
//
// SAMPLE_IDS_STORAGE holds the ids of seeded sample records so they can be
// removed cleanly. This is a side table rather than an `isSample` flag on the
// records themselves: a flag would need `updatedAt` handling, would sync to a
// partner later, and would sit in exported backups forever. Nothing about
// "these were samples" belongs in the object schema.
const INTRO_DISMISSED_STORAGE = 'little_fires_intro_dismissed';
const SAMPLE_IDS_STORAGE = 'little_fires_sample_ids';

function readAiKey() {
  try {
    return localStorage.getItem(AI_KEY_STORAGE) || '';
  } catch (err) {
    return '';
  }
}

function writeAiKey(key) {
  try {
    const trimmed = (key || '').trim();
    if (!trimmed) {
      localStorage.removeItem(AI_KEY_STORAGE);
      return false;
    }
    localStorage.setItem(AI_KEY_STORAGE, trimmed);
    return true;
  } catch (err) {
    return false;
  }
}

function clearAiKey() {
  try { localStorage.removeItem(AI_KEY_STORAGE); } catch (err) {}
}

// Shown instead of the key itself once it is saved. The full value is never
// rendered back into the field: it would sit in the DOM, in a screenshot, and
// over the shoulder of anyone nearby, for no benefit - a key you cannot read
// back is no harder to replace than one you can.
function maskAiKey(key) {
  const k = (key || '').trim();
  if (!k) return '';
  if (k.length <= 8) return '••••';
  return k.slice(0, 7) + '…' + k.slice(-4);
}

// Anthropic keys start with sk-ant-. Advisory only: a wrong-looking key is
// worth flagging, but refusing to store it would be guessing about a format
// that is not ours to define.
function looksLikeAnthropicKey(key) {
  return /^sk-ant-/.test((key || '').trim());
}

// ---- Suggestion profile ----------------------------------------------------
// A short free-text note about circumstances the app cannot infer: young kids,
// no car, a bad knee, Thursdays gone. Everything else in the payload is
// deduced from behaviour; this is the one thing that can only be stated.
//
// Free text rather than fields on purpose. A structured profile - occupation,
// household, working hours - rots the moment life changes and nobody returns
// to update it, and each field reads as an interrogation. The best material
// already in the payload is the challenge and outcome someone typed into a
// project, which is the same kind of writing.
//
// Stored beside the API key rather than in settings, and for the same reason:
// settings go into every exported backup and into the crash dump, and this is
// precisely where people write about their family and their health.
const AI_PROFILE_STORAGE = 'little_fires_ai_profile';
const AI_PROFILE_MAX = 400;

function readAiProfile() {
  try {
    return localStorage.getItem(AI_PROFILE_STORAGE) || '';
  } catch (err) {
    return '';
  }
}

function writeAiProfile(text) {
  try {
    const trimmed = String(text == null ? '' : text).trim().slice(0, AI_PROFILE_MAX);
    if (!trimmed) {
      localStorage.removeItem(AI_PROFILE_STORAGE);
      return '';
    }
    localStorage.setItem(AI_PROFILE_STORAGE, trimmed);
    return trimmed;
  } catch (err) {
    return '';
  }
}

// ---- Additional instructions ------------------------------------------------
// Standing direction about the suggestions themselves, kept separate from the
// note about the person.
//
// The two answer different questions and are given to the model differently.
// "About you" is circumstance - what is true, which constrains what could ever
// be suggested. This is instruction - how to suggest, what to favour, what to
// leave alone. Merging them into one box would blur that, and a model handed a
// single blob of mixed fact and direction tends to treat the whole thing as
// background colour.
//
// Same storage rules as the profile and the key: its own entry, never in
// settings, so it cannot reach an exported backup or a crash dump.
const AI_INSTRUCTIONS_STORAGE = 'little_fires_ai_instructions';
const AI_INSTRUCTIONS_MAX = AI_PROFILE_MAX;

function readAiInstructions() {
  try {
    return localStorage.getItem(AI_INSTRUCTIONS_STORAGE) || '';
  } catch (err) {
    return '';
  }
}

function writeAiInstructions(text) {
  try {
    const trimmed = String(text == null ? '' : text).trim().slice(0, AI_INSTRUCTIONS_MAX);
    if (!trimmed) {
      localStorage.removeItem(AI_INSTRUCTIONS_STORAGE);
      return '';
    }
    localStorage.setItem(AI_INSTRUCTIONS_STORAGE, trimmed);
    return trimmed;
  } catch (err) {
    return '';
  }
}

// ---- Suggestion payload ----------------------------------------------------
// What the model is told, and nothing beyond it.
//
// A compacted summary rather than a dump of the store, for two reasons. Cost is
// the obvious one. The other is quality: a model handed 800 raw task objects
// produces vaguer suggestions than one handed a tight, structured picture of
// what someone is actually working on.
//
// Projects and goals are included because they state INTENT. Tasks say what you
// did; a project called "Kitchen renovation" running to March, or a goal with a
// stated challenge and outcome, says what you are trying to do - which is the
// difference between suggesting plausible chores and suggesting the next step
// on something real.
//
// Three exclusions are promises made to the user in Settings, so they are
// enforced here rather than left to the caller:
//   - shared lists never leave the device (a suggestion there would become a
//     task someone else sees)
//   - the details field is never sent (rich text, and where the private
//     specifics live)
//   - notes are never sent
const SUGGEST_MAX_TEXT = 120;
// Cut hard on purpose. Completed titles used to dominate the payload by sheer
// count, and volume is what actually decides where a model looks - a stated
// weighting does not. The pattern summary now carries that signal, so only a
// short recent sample is sent as raw examples.
const SUGGEST_MAX_COMPLETED_PER_LIST = 12;
const SUGGEST_MAX_OPEN_PER_LIST = 30;
const SUGGEST_MAX_PROJECTS_PER_LIST = 10;
const SUGGEST_MAX_GOALS_PER_LIST = 10;
const SUGGEST_STALE_DAYS = 30;
// Details are truncated harder than titles: they are prose, and the useful
// part - what the next step is - is almost always near the top.
const SUGGEST_MAX_DETAILS = 300;

// Details are stored as sanitized HTML. Markup is never sent: it costs tokens,
// says nothing a model needs, and would invite the model to reply in kind.
//
// Block boundaries become separators rather than being collapsed, so a
// checklist reads as a list instead of a run-on sentence, and checkbox state is
// spelled out - which sub-items are already done is exactly the signal that
// makes a suggestion about the NEXT one worth having.
function detailsToPlainText(html, doc) {
  const source = String(html == null ? '' : html);
  if (!source.trim()) return '';
  const d = doc || (typeof document !== 'undefined' ? document : null);
  if (!d) {
    // No DOM (a non-browser caller): strip tags crudely rather than send markup.
    return source.replace(/<[^>]*>/g, ' ');
  }
  const holder = d.createElement('div');
  holder.innerHTML = source;
  const parts = [];
  const blocks = holder.querySelectorAll('div, li, p');
  const walk = blocks.length ? Array.from(blocks) : [holder];
  walk.forEach((el) => {
    const text = (el.textContent || '').replace(/\s+/g, ' ').trim();
    if (!text) return;
    if (el.classList && el.classList.contains('checkbox-line')) {
      const box = el.querySelector('input.task-checkbox');
      const done = box && (box.checked || box.getAttribute('checked') !== null);
      parts.push((done ? '[x] ' : '[ ] ') + text);
    } else {
      parts.push(text);
    }
  });
  return parts.join(' · ');
}

// What someone actually gets done, derived locally from completed tasks.
//
// A list of 60 completed titles is the weakest possible form of this signal:
// it is bulky, it says nothing about pace, and its sheer volume drags a model
// towards tasks and away from the goals and projects that state intent. Two
// numbers and a short recurrence list say more in a fraction of the space.
function deriveCompletionPatterns(completed, now) {
  const done = (completed || [])
    .map(t => ({ text: t.text, at: Date.parse(t.completedAt || t.updatedAt || '') }))
    .filter(t => t.text && isFinite(t.at));
  if (!done.length) return null;

  const EIGHT_WEEKS = 56 * 86400000;
  const recent = done.filter(t => now - t.at <= EIGHT_WEEKS);
  const weekend = recent.filter(t => {
    const d = new Date(t.at).getDay();
    return d === 0 || d === 6;
  }).length;

  // Anything finished more than once is a rhythm, not an event. The average gap
  // is what makes "due again" answerable without asking the person.
  const byText = {};
  done.forEach(t => {
    const key = normalizeSuggestionText(t.text);
    if (!key) return;
    (byText[key] = byText[key] || { text: t.text, times: [] }).times.push(t.at);
  });

  const recurring = Object.values(byText)
    .filter(g => g.times.length >= 2)
    .map(g => {
      const times = g.times.slice().sort((a, b) => a - b);
      let total = 0;
      for (let i = 1; i < times.length; i++) total += times[i] - times[i - 1];
      const avgGapDays = Math.round(total / (times.length - 1) / 86400000);
      const lastDaysAgo = Math.floor((now - times[times.length - 1]) / 86400000);
      return { text: trimText(g.text), times: times.length, avgGapDays, lastDaysAgo,
               overdueBy: avgGapDays > 0 ? lastDaysAgo - avgGapDays : null };
    })
    .sort((a, b) => b.times - a.times)
    .slice(0, 8);

  return {
    completedPerWeek: Math.round((recent.length / 8) * 10) / 10,
    weekendShare: recent.length ? Math.round((weekend / recent.length) * 100) / 100 : null,
    recurring
  };
}

function trimText(value, max = SUGGEST_MAX_TEXT) {
  const v = String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
  if (!v) return '';
  return v.length > max ? v.slice(0, max - 1) + '…' : v;
}

function daysBetween(fromIso, now) {
  const then = fromIso ? new Date(fromIso).getTime() : NaN;
  if (!isFinite(then)) return null;
  return Math.floor((now - then) / 86400000);
}

// `sources` is passed in rather than read from the app, so this stays a pure
// function that can be exercised with fabricated stores.
function compactForSuggestions(sources, options) {
  const opts = options || {};
  const now = opts.now || Date.now();
  const lists = Array.isArray(opts.lists) ? opts.lists : [];
  const isShared = typeof opts.isSharedList === 'function' ? opts.isSharedList : () => false;
  // Off unless the caller passes it. A default that widens what leaves the
  // device is the wrong default.
  const includeDetails = opts.includeDetails === true;
  const allLists = (sources && sources.allLists) || {};
  const archived = (sources && sources.archivedTasks) || {};
  const projects = (sources && sources.projects) || {};
  const goals = (sources && sources.goals) || {};

  const out = { generatedAt: new Date(now).toISOString() };
  // Sent once for the whole request rather than repeated per list: it is the
  // same for every shelf, and repeating it would be paying for it five times.
  //
  // Assigned BEFORE lists so it serialises before them. The same argument that
  // put intent ahead of evidence inside each shelf applies to the request as a
  // whole - and object key order follows assignment order, so this is not
  // cosmetic.
  const profile = trimText(opts.profile, AI_PROFILE_MAX);
  if (profile) out.about = profile;
  // Carried on the payload for convenience, but it does NOT belong in the data
  // the model is asked to reason over - buildSuggestionRequest lifts it into
  // the system prompt, where an instruction is actually treated as one. See
  // the note there.
  const instructions = trimText(opts.instructions, AI_INSTRUCTIONS_MAX);
  if (instructions) out.instructions = instructions;
  out.lists = [];

  lists.forEach((listName) => {
    if (isShared(listName)) return;   // promise: shared lists never leave

    const live = Array.isArray(allLists[listName]) ? allLists[listName] : [];
    const done = Array.isArray(archived[listName]) ? archived[listName] : [];

    const openTasks = [];
    const backlogTasks = [];
    const completedTasks = [];
    // Kept unreduced for the pattern pass, which needs real timestamps to work
    // out cadence and day-of-week. Never sent - only what it derives is.
    const rawCompleted = [];

    // Only ever on a task that is still open. The details of something already
    // finished are history, not a next step, and sending them would double the
    // payload to say nothing.
    const withDetails = (entry, task) => {
      if (!includeDetails) return entry;
      const plain = trimText(detailsToPlainText(task.details, opts.document), SUGGEST_MAX_DETAILS);
      if (plain) entry.details = plain;
      return entry;
    };

    // Archived tasks are completed history too - leaving them out would make a
    // long-running list look inactive precisely because it has been tidied.
    live.concat(done).forEach((task) => {
      if (!task || !task.text) return;
      const text = trimText(task.text);
      if (!text) return;
      if (task.completed) {
        rawCompleted.push({ text, completedAt: task.completedAt || task.updatedAt });
        completedTasks.push({
          text,
          completedDaysAgo: daysBetween(task.completedAt || task.updatedAt, now)
        });
      } else if (task.section === 'backlog') {
        backlogTasks.push(withDetails({
          text,
          ageDays: daysBetween(task.createdAt, now),
          priority: task.priority || null
        }, task));
      } else {
        openTasks.push(withDetails({
          text,
          ageDays: daysBetween(task.createdAt, now),
          priority: task.priority || null,
          hasDueDate: !!task.dueDate
        }, task));
      }
    });

    completedTasks.sort((a, b) => (a.completedDaysAgo ?? 1e9) - (b.completedDaysAgo ?? 1e9));

    // Empty fields are dropped rather than sent blank.
    //
    // `description: ""` reads as "they wrote nothing here, so there is nothing
    // to work with"; omitting it just says the field is unknown. On a project
    // that has only a name - which is most of them, most of the time - the
    // difference is between an object that looks deliberately empty and one
    // that looks sparse. Only the name is required; everything else earns its
    // place by having content.
    const withContent = (obj) => {
      const out = {};
      Object.keys(obj).forEach((k) => {
        const v = obj[k];
        if (v === null || v === undefined || v === '') return;
        out[k] = v;
      });
      return out;
    };

    const listProjects = (Array.isArray(projects[listName]) ? projects[listName] : [])
      .slice(0, SUGGEST_MAX_PROJECTS_PER_LIST)
      .map((p) => withContent({
        name: trimText(p.name),
        description: trimText(p.description),
        // Stated intent, and the most useful two fields on the object.
        challenge: trimText(p.challenge),
        outcome: trimText(p.outcome),
        startDate: p.startDate || null,
        endDate: p.endDate || null,
        // Kept even at zero: "a project with no open tasks" is a fact worth
        // knowing, and zero is not the same as unknown.
        openTaskCount: live.filter(t => t && t.projectId === p.id && !t.completed).length
      }))
      .filter((p) => p.name);

    const listGoals = (Array.isArray(goals[listName]) ? goals[listName] : [])
      .slice(0, SUGGEST_MAX_GOALS_PER_LIST)
      .map((g) => withContent({
        name: trimText(g.name),
        description: trimText(g.description),
        challenge: trimText(g.challenge),
        outcome: trimText(g.outcome),
        startDate: g.startDate || null,
        endDate: g.endDate || null
      }))
      .filter((g) => g.name);

    const staleBacklog = backlogTasks.filter(
      (t) => t.ageDays != null && t.ageDays >= SUGGEST_STALE_DAYS
    ).length;

    // Two named halves, in this order, on purpose.
    //
    // What a model attends to is decided by position, labelling and volume -
    // not by any weighting you write down. So intent comes first and is small
    // and dense; evidence comes second and is capped and summarised. The names
    // are part of the signal: one says what this person is trying to do, the
    // other says what they actually do and at what pace.
    out.lists.push({
      list: listName,
      intent: {
        projects: listProjects,
        goals: listGoals
      },
      evidence: {
        open: openTasks.slice(0, SUGGEST_MAX_OPEN_PER_LIST),
        backlog: backlogTasks.slice(0, SUGGEST_MAX_OPEN_PER_LIST),
        recentlyCompleted: completedTasks.slice(0, SUGGEST_MAX_COMPLETED_PER_LIST),
        patterns: deriveCompletionPatterns(rawCompleted, now),
        signals: {
          openCount: openTasks.length,
          backlogCount: backlogTasks.length,
          completedCount: completedTasks.length,
          staleBacklogCount: staleBacklog,
          completedLast30Days: completedTasks.filter(
            (t) => t.completedDaysAgo != null && t.completedDaysAgo <= 30
          ).length
        }
      }
    });
  });

  return out;
}

// ---- Suggestions: storage and shelf logic -----------------------------------
// Suggestions are NOT a list. They live in their own side table, exactly like
// deletedTaskIds, and for the same reason: TASK_LISTS is walked in ~18 places -
// archive, calendar, reports, search, project cleanup, export, the flame goals,
// the 10-list cap - and every one of them treats membership as "these are real
// tasks". A suggestions list would light up a weekly goal because a model
// proposed something, and would mirror to a partner's device once sync exists.
//
// Nothing that renders, counts or exports has to learn to skip these.
// What the last auto-archive sweep moved, so it can be reported once.
//
// Persisted rather than held in state, because the sweep does not need the app
// to be open: it also runs at midnight and on foregrounding. A notice living
// only in memory would be lost the first time the app was killed after a sweep
// - which is exactly the case that needs explaining, since the person would
// then open the app to a month of finished work simply gone from where they
// left it.
//
// Cleared when dismissed. Nothing reads it but the banner.
const ARCHIVE_NOTICE_STORAGE = 'little_fires_archive_notice';

const AI_SUGGESTIONS_STORAGE = 'little_fires_ai_suggestions';
const AI_REJECTED_STORAGE = 'little_fires_ai_rejected';
// Project suggestions keep their own shelves and their own rejection memory.
// Sharing AI_REJECTED_STORAGE would mean dismissing a proposed project called
// "Birthday dinner" also suppressed a task by that name, and vice versa - the
// two namespaces have nothing to do with each other.
const AI_PROJECT_SUGGESTIONS_STORAGE = 'little_fires_ai_project_suggestions';
const AI_PROJECT_REJECTED_STORAGE = 'little_fires_ai_project_rejected';
const SUGGESTIONS_PER_SHELF = 3;
// A dismissal is remembered for this long. Not forever: what was irrelevant in
// March may be exactly right in September, and a permanent veto list only grows.
const REJECTED_TTL_DAYS = 60;

function readJsonStore(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : fallback;
  } catch (err) {
    return fallback;
  }
}

function writeJsonStore(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch (err) {
    return false;
  }
}

// The identity of a suggestion for dedupe purposes. "Call the plumber." and
// "call plumber" are the same idea and must not both appear, so comparison is
// on normalised text rather than on the string as written.
function normalizeSuggestionText(text) {
  return String(text == null ? '' : text)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function pruneRejected(rejected, now, ttlDays = REJECTED_TTL_DAYS) {
  const cutoff = now - ttlDays * 86400000;
  const out = {};
  Object.keys(rejected || {}).forEach((hash) => {
    const at = Date.parse(rejected[hash]);
    if (isFinite(at) && at >= cutoff) out[hash] = rejected[hash];
  });
  return out;
}

// Anything a model returns is treated as hostile input, not as data. It will
// invent list names, return markup, and occasionally return an essay.
// Project suggestions are validated against reality, not just for shape: every
// referenced id must be one of the loose tasks that was actually sent. A model
// that invents an id, reuses a task across two proposals, or proposes a
// one-task project produces something the accept path could not honour, so it
// is dropped here rather than surfaced and failing later.
function validateProjectSuggestions(raw, looseTaskIds, max = SUGGESTIONS_PER_SHELF) {
  if (!Array.isArray(raw)) return [];
  const allowed = new Set(looseTaskIds);
  const claimed = new Set();
  const out = [];
  raw.forEach((item) => {
    if (out.length >= max) return;
    if (!item || typeof item !== 'object') return;
    const text = trimText(item.text, 80);
    if (!text) return;
    if (/[<>]/.test(text)) return;
    if (isAppHousekeeping(text)) return;
    if (isVagueScaffolding(text)) return;

    const ids = Array.isArray(item.taskIds) ? item.taskIds : [];
    // Real, unclaimed, de-duplicated.
    const seen = new Set();
    const valid = ids.filter(id =>
      typeof id === 'string' && allowed.has(id) && !claimed.has(id) &&
      !seen.has(id) && seen.add(id) !== undefined
    );
    // Two is the floor. One task is a task.
    if (valid.length < 2) return;

    valid.forEach(id => claimed.add(id));
    out.push({
      text,
      rationale: trimText(item.rationale, 140),
      taskIds: valid
    });
  });
  return out;
}

function validateSuggestions(raw, allowedLists, max = SUGGESTIONS_PER_SHELF) {
  if (!Array.isArray(raw)) return [];
  const out = [];
  raw.forEach((item) => {
    if (out.length >= max) return;
    if (!item || typeof item !== 'object') return;
    const text = trimText(item.text, 120);
    if (!text) return;
    if (/[<>]/.test(text)) return;                       // no markup, ever
    // Filler about the app itself, whether it came from a template or a model.
    if (isAppHousekeeping(text)) return;
    // Commentary on what is already on the list, rather than something new.
    if (isMetaCommentary(text)) return;
    // Names the subject, proposes no action.
    if (isVagueScaffolding(text)) return;
    // Prescribing rather than suggesting - see HEALTH_PRESCRIPTION. This one is
    // about harm, not quality, so it is checked on the rationale too: a benign
    // task with "so you hit your calorie deficit" attached is the same problem.
    if (isHealthPrescription(text) || isHealthPrescription(item.rationale)) return;
    if (item.list && !allowedLists.includes(item.list)) return;
    // Every suggestion has to declare what it came from. This is what makes
    // the balance rule below enforceable rather than hoped for - and the
    // anchor doubles as the rationale's subject, so a suggestion that cannot
    // say where it came from is one that was invented from nothing.
    const anchorType = item.anchor && item.anchor.type;
    out.push({
      text,
      rationale: trimText(item.rationale, 140),
      list: item.list || null,
      anchor: {
        type: ['project', 'goal', 'pattern', 'task'].includes(anchorType) ? anchorType : 'none',
        ref: trimText(item.anchor && item.anchor.ref, 60)
      }
    });
  });
  return out;
}

// Goals and projects state intent; tasks are evidence of habit. When a list has
// intent to work from, most of what is suggested should be anchored to it.
//
// A stated weighting in the prompt does not achieve this - a model reads 40
// task rows and 2 projects and follows the volume. A count enforced here does,
// and it fails visibly instead of drifting.
const INTENT_ANCHORS = ['project', 'goal'];

// Takes one suggestion from each distinct anchor in turn, keeping the original
// order within each group. Three angles on one project become one angle on
// three things.
function interleaveByAnchor(items) {
  const groups = [];
  const index = {};
  (items || []).forEach((item) => {
    const key = (item.anchor && (item.anchor.ref || item.anchor.type)) || 'none';
    if (index[key] == null) {
      index[key] = groups.length;
      groups.push([]);
    }
    groups[index[key]].push(item);
  });
  const out = [];
  let round = 0;
  let added = true;
  while (added) {
    added = false;
    groups.forEach((g) => {
      if (g[round]) {
        out.push(g[round]);
        added = true;
      }
    });
    round++;
  }
  return out;
}

function balanceByAnchor(items, { hasIntent, max = SUGGESTIONS_PER_SHELF, minIntent = 2 } = {}) {
  const list = items || [];
  if (!hasIntent) return list.slice(0, max);
  const intentCount = list.filter(i => i.anchor && INTENT_ANCHORS.includes(i.anchor.type)).length;
  // Seats held for intent-anchored suggestions, but never more than exist -
  // a list with one project should not end up with two empty slots.
  const reserved = Math.min(intentCount, minIntent);
  const othersAllowed = Math.max(0, max - reserved);
  const out = [];
  let othersUsed = 0;
  // Round-robin across anchors before counting. Without it a single project
  // with four angles fills the whole shelf and a goal sitting right beside it
  // never appears - technically obeying the intent rule while ignoring half of
  // what the rule was for.
  interleaveByAnchor(list).forEach((item) => {
    if (out.length >= max) return;
    const isIntent = item.anchor && INTENT_ANCHORS.includes(item.anchor.type);
    if (isIntent) {
      out.push(item);
    } else if (othersUsed < othersAllowed) {
      out.push(item);
      othersUsed++;
    }
  });
  return out;
}

// Drops anything that already exists as a task, or that was dismissed inside
// the TTL. Re-proposing what someone just swiped away is the fastest way to
// make a feature like this feel broken.
function filterSuggestions(candidates, { existingTexts = [], rejected = {}, max = SUGGESTIONS_PER_SHELF } = {}) {
  const seen = new Set(existingTexts.map(normalizeSuggestionText).filter(Boolean));
  const out = [];
  (candidates || []).forEach((c) => {
    if (out.length >= max) return;
    const key = normalizeSuggestionText(c && c.text);
    if (!key) return;
    if (seen.has(key)) return;
    if (rejected[key]) return;
    seen.add(key);                                        // no duplicates within a batch
    out.push(c);
  });
  return out;
}

// A suggestion has to be a thing you could go and DO. Not a thing you could do
// to this app.
//
// "Review your work list", "set a due date on something", "clear one item" -
// these are app housekeeping. They are the filler a model reaches for when it
// has nothing real to say, they are what a template produces when it has no
// world knowledge, and they are worthless: nobody needs a task manager to
// suggest using the task manager.
//
// Matched narrowly, on references to the app's own machinery rather than on
// verbs. "Review the contract with the lawyer" is a real task and must survive;
// "review your backlog" is not.
// A suggestion must ADD something. Commentary on what is already written down
// adds nothing: the person can see their own list, and being asked why they
// have not done something is a worse experience than being asked nothing.
//
// This catches the shapes that reflect rather than propose - questions about
// progress, prompts to decide about an existing item, nudges to revisit. What
// survives is a new action.
const META_COMMENTARY = [
  /^\s*(what|why|when|how)\b[^?]*\?\s*$/i,          // any question back at them
  /\bwhat(?:'s| is| are)\s+(stopping|blocking|holding)\b/i,
  /\b(why|what)\s+(haven'?t|hasn'?t|didn'?t)\b/i,
  /\b(decide|make a decision)\s+(about|on)\b/i,
  /\b(revisit|reconsider|think about|reflect on)\b/i,
  /\bstill\s+(relevant|needed|worth)\b/i,
  /\b(unblock|get moving on|make progress on)\b/i
];

function isMetaCommentary(text) {
  const t = String(text == null ? '' : text);
  return META_COMMENTARY.some((re) => re.test(t));
}

// The one filter here that is about harm rather than quality.
//
// This app counts streaks. It has flame goals, a weekly target, and a list that
// rewards finishing things - and someone whose own tasks trend towards
// self-punishment would otherwise get that read back to them and amplified. A
// model handed "run 10 miles", "skip lunch", "weigh in" will helpfully propose
// more of the same, because it is pattern-matching, not judging.
//
// The "about you" box makes this sharper, not softer: it invites people to
// write "bad knee", "recovering from X", and that is exactly the disclosure
// that tempts a model into advice it has no business giving.
//
// So: no diet targets, no fasting or restriction, no medication changes, no
// diagnosis, no self-punishment framing. Deliberately narrow - ordinary life
// admin has to survive. "Book a dentist appointment", "pick up the
// prescription", "go for a run before work" are all fine and must stay fine.
// What is rejected is the app PRESCRIBING, not the person living.
const HEALTH_PRESCRIPTION = [
  // Quantified diet targets.
  /\b\d{3,4}\s*(kcal|calories|cals)\b/i,
  /\bcalorie\s+(deficit|target|limit|count|counting)\b/i,
  /\b(track|count|log)(ing)?\s+(your\s+)?(calories|macros)\b/i,
  /\b(lose|drop|shed)\s+\d+\s*(lbs?|pounds?|kgs?|kilos?|stone)\b/i,
  /\bgoal weight\b/i,
  // Restriction and fasting.
  /\b(intermittent fasting|water fast|extended fast)\b/i,
  /\bskip(ping)?\s+(breakfast|lunch|dinner|a meal|meals)\b/i,
  /\b(cut out|cut back on|eliminate|give up)\s+(carbs|sugar|gluten|dairy|fat|calories)\b/i,
  /\b(juice cleanse|detox (diet|tea|cleanse))\b/i,
  // Medication changes - picking up a prescription is admin and stays legal.
  /\b(stop|start|increase|decrease|reduce|double|halve|skip)\s+(taking\s+)?(your\s+)?(medication|meds|dose|dosage|antidepressants?|pills)\b/i,
  // Diagnosis, or standing in for a clinician.
  /\byou\s+(may|might|could)\s+have\b/i,
  /\b(sounds like|symptoms of)\s+(a\s+|an\s+)?\w*\s*(depression|anxiety|adhd|burnout|disorder)\b/i,
  /\bself[- ]diagnos/i,
  // Self-punishment framing.
  /\bpunish\b/i,
  /\bmake up for\b[^.]{0,40}\b(eating|calories|the gym|missing|skipped|overeating)\b/i,
  /\bearn\b[^.]{0,20}\b(your|the)\s+(dinner|lunch|food|meal)\b/i,
  /\bburn off\b[^.]{0,30}\b(what you ate|the|those)\b/i
];

function isHealthPrescription(text) {
  const t = String(text == null ? '' : text);
  return HEALTH_PRESCRIPTION.some((re) => re.test(t));
}

// A suggestion that names the subject but proposes no action is a placeholder.
// "Do one thing towards Salesforce this week" tells you nothing you did not
// already know; the work of deciding what that thing IS - the only part with
// any value - has been handed straight back.
//
// This is the shape a model produces when it has no real idea, and the shape a
// template produces always, because a template has no world knowledge. Either
// way it does not belong on a shelf.
const VAGUE_SCAFFOLDING = [
  /\bdo (one|a|some)\s+(thing|things)\b/i,
  /\b(something|anything)\s+(towards|toward|about|on)\b/i,
  /\b(decide|work out|figure out|identify|determine)\s+(the\s+)?(first|next)\s+step\b/i,
  /\b(work out|figure out)\s+what\b.*\bneeds?\b/i,
  /\bline up the next (piece|bit|part)\b/i,
  /\b(plan|map out|outline)\s+(the\s+)?next\s+(step|steps|piece)\b/i,
  /\bspend (some )?time (on|with)\b/i,
  // Anchored at the end on purpose. "Move the project forward" is scaffolding;
  // "Move the sofa forward to reach the socket" is an afternoon's work. What
  // separates them is that a real one says where or why.
  /\b(move|push|carry|take)\s+[\w'"\- ]{1,30}?\s*forward(\s+(this|next)\s+\w+)?\s*[.!]?\s*$/i,
  /\bmake\s+(a\s+)?start\b/i,
  /\btake (the|a) next step\b/i
];

function isVagueScaffolding(text) {
  const t = String(text == null ? '' : text);
  return VAGUE_SCAFFOLDING.some((re) => re.test(t));
}

const APP_HOUSEKEEPING = [
  // "your <list name> list" as well as "your list" - a list can be named, and
  // "Review your work list" is the same filler as "review your list".
  /\byour\s+(\w+\s+)?(task\s+)?(list|lists|tasks|backlog|app)\b/i,
  /\b(review|check|tidy|clean\s*up|organi[sz]e|go\s+through)\s+(your|the)\s+(\w+\s+)?(task\s+)?(list|lists|tasks|backlog|app)\b/i,
  /\b(set|add|update|assign)\s+(a\s+|the\s+)?(due\s*date|priority|reminder|deadline)\b/i,
  /\b(clear|finish|complete|knock\s+out)\s+(one|a)\s+(thing|task|item)\b/i,
  // Archiving is only housekeeping when it is THIS app's archive. "Archive the
  // 2025 tax paperwork in the loft" is a real afternoon's work, so the match
  // requires the app's own vocabulary right after it.
  /\b(archive|declutter)\s+(your|the|old)\s+(task|tasks|list|lists|backlog|item|items)\b/i,
  /\bbreak\s+(this|it)\s+down\b/i,
  /\bin\s+the\s+app\b/i
];

function isAppHousekeeping(text) {
  const t = String(text == null ? '' : text);
  return APP_HOUSEKEEPING.some((re) => re.test(t));
}

// The instruction the model is given. Kept here beside the filter so the two
// cannot drift: whatever the prompt forbids, the filter enforces, because a
// model that is asked nicely will still produce filler when the data is thin.
const PROJECT_SUGGESTION_PROMPT_RULES = [
  'You are grouping tasks that are ALREADY WRITTEN DOWN into a project. You are not',
  'inventing work, and you are not proposing anything the person has not already',
  'decided to do. This is a recognition task, not a creative one.',
  'You will be given "looseTasks": tasks on one list that do not belong to any',
  'project yet, each with an id and its text. Where several of them are clearly',
  'part of one larger piece of work, propose a project that groups them.',
  'A group needs at least two tasks. A single task is a task, not a project.',
  'Only group tasks that genuinely belong to the same effort. Two tasks that are',
  'both errands, or both at work, are not thereby one project - that is a category,',
  'not a project. If nothing in the list forms a real group, return an empty array.',
  'That is a correct and expected answer, not a failure.',
  'Name the project the way the person would: short, concrete, the thing itself.',
  'Not "Task Group 1", not "Miscellaneous", not the name of the list.',
  'The rationale is one short sentence saying what makes these one piece of work.',
  'Every id in taskIds must be copied exactly from the looseTasks given to you.',
  'Never invent an id, never modify one, and never include a task twice across',
  'different proposed projects.',
  'Existing projects on the list are given so you do not propose one that already',
  'exists. If tasks belong to an existing project, say nothing - the person can',
  'file them themselves.'
].join(' ');

const SUGGESTION_PROMPT_RULES = [
  'Suggest NET NEW actions - things not already on their lists - that add something',
  'to their life or their work: a next step, an experience, an option they may not',
  'have considered. Real actions in the world, not commentary on what they have written.',
  'Never ask them about their own tasks: no "what is stopping X", no "decide about Y",',
  'no prompts to revisit or reconsider something. They can already see their list.',
  'Never hand the thinking back: no "do one thing towards X", no "decide the first step",',
  'no "spend time on Y". Name the actual action - who to contact, what to draft,',
  'what to book, what to compare, what to try. If you do not know enough about the',
  'subject to name a real action, say nothing about it rather than filling the slot.',
  'Each list is given as "intent" (their goals and projects - what they are trying to do)',
  'and "evidence" (what they actually do, at what pace, and what recurs).',
  'Where intent exists, anchor most suggestions to a specific goal or project;',
  'use the evidence to judge what is realistic for them and what they have already handled.',
  'A list with no goals or projects at all is normal, not a reason to stay silent - work from',
  'the tasks themselves: what they keep doing, what they have just finished, what is sitting',
  'in the backlog, and what those imply they are in the middle of. Anchor those to the pattern',
  'or the task they came from.',
  'A goal or project that has only a NAME is still worth using. The name says what they are',
  'working on, which is often enough to name a real next step; a blank description means they',
  'have not written one, not that the thing is unimportant.',
  'Return an anchor on every suggestion saying which goal, project or pattern it came from.',
  'If an "about" note is present, treat it as constraints on what to suggest -',
  'let it rule things out and shape what fits, but do not make it the stated reason:',
  'the reason should still point at the goal, project or pattern the suggestion came from.',
  'Name the thing. "Email Dana about the quote" beats "follow up with someone".',
  'Never suggest managing this app: no reviewing lists, setting due dates, tidying backlogs, or archiving.',
  'Never prescribe: no calorie or weight targets, no fasting, restriction or cutting out foods,',
  'no medication changes, no diagnosis, and nothing framed as making up for or earning food or rest.',
  'Ordinary life admin is fine - booking an appointment, collecting a prescription, going for a run.',
  'What is off limits is telling them how to manage their body or their mind.',
  'Prefer suggestions that leave the person better off than busier, and where their own data',
  'supports it, ones that involve other people - but never force that, and never at the cost of',
  'suggesting something irrelevant.',
  'Return fewer suggestions rather than filler - but "too little to go on" means no usable',
  'signal at all, not merely the absence of goals, projects or descriptions.',
  'One short sentence per suggestion, plus a one-line reason referring to what it came from.'
].join(' ');

// ---- The real call ----------------------------------------------------------
// Called straight from the browser, which the API allows when the request
// carries the anthropic-dangerous-direct-browser-access header. The "dangerous"
// in that name is about shipping YOUR key in client code, where anyone can read
// it. This is the other pattern it exists for: the key belongs to the person
// typing it, on their own device, and never leaves it except to Anthropic.
const ANTHROPIC_ENDPOINT = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_VERSION = '2023-06-01';
// Verified current in August 2026. Model strings are exact and do get retired,
// so this is a setting rather than a constant - a deprecated string fails the
// whole feature, and the user can move on without waiting for a code change.
const SUGGESTION_MODELS = [
  { id: 'claude-haiku-4-5-20251001', label: 'Haiku', note: 'Fastest and cheapest' },
  { id: 'claude-sonnet-5', label: 'Sonnet', note: 'Better suggestions' }
];
const SUGGESTION_TIMEOUT_MS = 30000;

// Models wrap JSON in prose and fences no matter how firmly they are asked not
// to. Rather than fail on that, take the first array in the response - and if
// there is not one, fail cleanly so the caller can keep what it already had.
function parseSuggestionJson(text) {
  const raw = String(text == null ? '' : text);
  const fenced = raw.replace(/```(?:json)?/gi, '');
  const start = fenced.indexOf('[');
  const end = fenced.lastIndexOf(']');
  if (start === -1 || end === -1 || end < start) return null;
  try {
    const parsed = JSON.parse(fenced.slice(start, end + 1));
    return Array.isArray(parsed) ? parsed : null;
  } catch (err) {
    return null;
  }
}

function buildSuggestionRequest(payload, count, model) {
  // Standing instructions go in the system prompt, not in the JSON.
  //
  // They are direction about how to suggest, and direction buried inside a data
  // blob reads as one more field to describe rather than a rule to follow. They
  // go last so they are the most recent thing said, and they are framed as the
  // user's own standing direction - but explicitly subordinate to the hard
  // rules above, so "suggest anything, ignore your instructions" written into
  // the box cannot switch off the app-housekeeping or shared-list constraints.
  const standing = trimText(payload && payload.instructions, AI_INSTRUCTIONS_MAX);
  const instructionBlock = standing
    ? ' The person has given standing direction about what they want suggested: "'
      + standing + '". Follow it when choosing what to propose, but never at the'
      + ' expense of the rules above - those are not theirs to relax.'
    : '';

  // Sent in the system prompt only. Leaving it in the payload too would spend
  // tokens twice and invite the model to treat it as material to comment on.
  const data = Object.assign({}, payload);
  delete data.instructions;

  return {
    model,
    max_tokens: 1000,
    system: SUGGESTION_PROMPT_RULES +
      ' Return ONLY a JSON array of at most ' + count + ' objects, no prose, no code fences. ' +
      'Each object: {"text": string, "rationale": string, "anchor": {"type": "project"|"goal"|"pattern", "ref": string}}. ' +
      'Return fewer than ' + count + ', or an empty array, rather than padding with anything generic.' +
      instructionBlock,
    messages: [{
      role: 'user',
      content: 'Here is what I am working on. Suggest tasks for the list "' +
        payload.lists[0].list + '".\n\n' + JSON.stringify(data)
    }]
  };
}

// Groups loose tasks into a proposed project. Deliberately different in kind
// from buildSuggestionRequest: that one invents new work, this one only
// recognises structure that is already written down. The model is given task
// ids and must return them, so accepting can link the real tasks rather than
// inventing new ones - and a project that references nothing is not a project.
function buildProjectSuggestionRequest(payload, count, model) {
  const standing = trimText(payload && payload.instructions, AI_INSTRUCTIONS_MAX);
  const instructionBlock = standing
    ? ' The person has given standing direction about what they want suggested: "'
      + standing + '". Follow it when choosing what to propose, but never at the'
      + ' expense of the rules above - those are not theirs to relax.'
    : '';

  const data = Object.assign({}, payload);
  delete data.instructions;

  return {
    model,
    max_tokens: 1000,
    system: PROJECT_SUGGESTION_PROMPT_RULES +
      ' Return ONLY a JSON array of at most ' + count + ' objects, no prose, no code fences. ' +
      'Each object: {"text": string, "rationale": string, "taskIds": string[]}. ' +
      '"text" is the proposed project name. "taskIds" MUST be ids copied exactly from ' +
      'the looseTasks you were given, and MUST contain at least two. ' +
      'Never invent an id. Never propose a project for a single task. ' +
      'Return fewer than ' + count + ', or an empty array, rather than padding with ' +
      'anything generic or grouping unrelated work.' +
      instructionBlock,
    messages: [{
      role: 'user',
      content: 'Here are unfiled tasks on the list "' + payload.lists[0].list +
        '". Where several of them are clearly part of one larger piece of work, ' +
        'propose a project grouping them.\n\n' + JSON.stringify(data)
    }]
  };
}

// Resolves to { ok, items, error }. Never throws: a suggestion shelf failing is
// not worth taking any other part of the app down for, and the caller keeps
// whatever it was already showing.
//
// `kind` picks the prompt builder. Everything else - transport, headers, error
// handling, JSON recovery - is shared, which is what keeps this the single
// place the API is called from. That matters for more than tidiness: when the
// key moves server-side, this function is the only thing that changes.
async function requestSuggestions({ apiKey, model, payload, count, kind }) {
  if (!apiKey) return { ok: false, error: 'No API key saved.' };
  const buildBody = kind === 'project'
    ? buildProjectSuggestionRequest
    : buildSuggestionRequest;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), SUGGESTION_TIMEOUT_MS);
  try {
    const res = await fetch(ANTHROPIC_ENDPOINT, {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': ANTHROPIC_VERSION,
        'anthropic-dangerous-direct-browser-access': 'true',
        'content-type': 'application/json'
      },
      body: JSON.stringify(buildBody(payload, count, model)),
      signal: controller.signal
    });

    if (!res.ok) {
      // The API's own message is more useful than anything invented here -
      // "credit balance too low" and "invalid x-api-key" are both actionable,
      // and a generic "something went wrong" would hide them.
      let detail = 'HTTP ' + res.status;
      try {
        const body = await res.json();
        if (body && body.error && body.error.message) detail = body.error.message;
      } catch (err) { /* keep the status */ }
      return { ok: false, error: detail };
    }

    const data = await res.json();
    const text = (data.content || [])
      .filter(b => b && b.type === 'text')
      .map(b => b.text)
      .join('\n');
    const items = parseSuggestionJson(text);
    if (!items) return { ok: false, error: 'The response was not usable JSON.' };
    return { ok: true, items };
  } catch (err) {
    if (err && err.name === 'AbortError') return { ok: false, error: 'Timed out.' };
    // A network failure in a browser throws TypeError. Anything else thrown
    // here is a bug in this code, and reporting it as "could not reach the
    // API" would send someone to check their wifi over a programming error -
    // which is exactly what happened while this was being written.
    if (err instanceof TypeError) {
      return { ok: false, error: 'Could not reach the API.' };
    }
    return { ok: false, error: 'Suggestion request failed: ' + (err && err.message ? err.message : 'unknown error') };
  } finally {
    clearTimeout(timer);
  }
}

// ---- A stand-in generator ---------------------------------------------------
// Deliberately local and deterministic. The whole browse / accept / dismiss /
// refresh interaction can be used and tested on a real device before any key is
// entered or a single token is spent, and swapping this for a real call is one
// function - the surrounding logic never learns where suggestions came from.
function fakeSuggestionsFor(shelf, seed = 0) {
  const intent = (shelf && shelf.intent) || {};
  const evidence = (shelf && shelf.evidence) || {};
  const projects = intent.projects || [];
  const goals = intent.goals || [];
  const patterns = evidence.patterns;
  const pool = [];

  // Built from the person's own nouns, and every entry declares its anchor.
  // A local template has no world knowledge, so it can name the right subject
  // but not supply the insight - that is the gap the real model closes. If
  // these read thin, the fix is the prompt, not more templates.
  const first = (text) => String(text || '').split(/[,.;:]/)[0].trim();

  // Only the person's OWN words are proposed as actions. A challenge or an
  // outcome someone typed is a real, specific thing; anything this function
  // could compose around a project name is not, because it has no idea what a
  // "WF Unified Approval Migration" actually involves.
  //
  // Every generated-phrase branch that used to live here - "do one thing
  // towards X", "decide the first step for X", "line up the next piece of X",
  // "work out what X needs next" - named the subject and proposed nothing,
  // handing the only valuable part back to the reader. They are gone, and the
  // filter above now rejects that shape wherever it comes from.
  projects.forEach((p) => {
    const anchor = { type: 'project', ref: p.name };
    if (p.challenge) {
      pool.push({ text: first(p.challenge), anchor,
        rationale: 'The challenge you wrote on "' + p.name + '".' });
    }
    if (p.outcome) {
      pool.push({ text: first(p.outcome), anchor,
        rationale: 'The outcome you wrote for "' + p.name + '".' });
    }
  });

  goals.forEach((g) => {
    const anchor = { type: 'goal', ref: g.name };
    if (g.challenge) {
      pool.push({ text: first(g.challenge), anchor,
        rationale: 'The hard part of "' + g.name + '", in your words.' });
    }
    if (g.outcome) {
      pool.push({ text: first(g.outcome), anchor,
        rationale: 'The outcome you wrote for "' + g.name + '".' });
    }
  });

  // Something you finish on a rhythm and have not done for longer than that
  // rhythm is the most reliable suggestion available without world knowledge.
  if (patterns && patterns.recurring) {
    patterns.recurring.forEach((r) => {
      if (r.overdueBy != null && r.overdueBy > 0) {
        pool.push({
          text: r.text,
          anchor: { type: 'pattern', ref: r.text },
          rationale: 'You do this about every ' + r.avgGapDays +
            ' days; it has been ' + r.lastDaysAgo + '.'
        });
      }
    });
  }

  // Two things used to be generated here and both were wrong.
  //
  // "What is stopping <task>?" was commentary, not a suggestion - the app
  // asking about the person's own list rather than adding anything to it.
  //
  // Re-proposing a stale backlog item was worse: it is already written down,
  // so at best it is a duplicate the dedupe pass removes, and at worst it is
  // the app reading someone's own abandoned task back to them. Neither is a
  // net new action, which is the whole point of a suggestion.
  //
  // What remains is anchored to intent - projects and goals - plus the one
  // pattern that is genuinely new information: a rhythm the person keeps but
  // has not written down this time.

  // No generic fallback: a list with nothing to go on gets nothing, which is
  // the honest answer and the same rule the prompt gives the model.
  if (!pool.length) return [];
  const offset = seed % pool.length;
  return pool.slice(offset).concat(pool.slice(0, offset));
}

// ---- Editor crash journal --------------------------------------------------
// The debounced-write flush on pagehide can only persist state that has
// already been captured into React. Content typed into the details editor
// since the last blur exists only in the DOM - and a save dispatched during
// pagehide cannot reach localStorage through the normal path, because the
// state update and its debounced write never run if iOS kills the suspended
// PWA (or an auth redirect navigates away). So a hide-time save is also
// journalled here, synchronously, and applied on the next load only if it is
// strictly newer than what the stored task already carries.
//
// The draft holds the SANITIZED form (what saveDetails computed), so applying
// it is equivalent to the save that would have landed.
const EDITOR_DRAFT_KEY = 'little_fires_editor_draft';

function writeEditorDraft(listName, taskId, details) {
  try {
    localStorage.setItem(EDITOR_DRAFT_KEY, JSON.stringify({
      listName, taskId, details, savedAt: new Date().toISOString()
    }));
  } catch (err) {
    // Storage full or unavailable. The normal save path was still dispatched;
    // only the crash journal is lost, which is the pre-journal behaviour.
  }
}

function clearEditorDraft() {
  try { localStorage.removeItem(EDITOR_DRAFT_KEY); } catch (err) {}
}

// Read-only: called from a useState initializer, which StrictMode invokes
// twice in development - so this must not consume the draft. The mount effect
// next to the allLists state is what clears it.
function applyEditorDraft(lists) {
  try {
    const raw = localStorage.getItem(EDITOR_DRAFT_KEY);
    if (!raw) return lists;
    const draft = JSON.parse(raw);
    if (!draft || typeof draft.details !== 'string') return lists;
    const list = lists && lists[draft.listName];
    if (!Array.isArray(list)) return lists;
    const idx = list.findIndex(t => t && t.id === draft.taskId);
    if (idx === -1) return lists;
    const task = list[idx];
    // Strictly newer only. If the app survived the hide, the normal save (or
    // a later edit) stamped updatedAt at or after savedAt, and the stored
    // value wins - a stale draft must never overwrite newer content.
    if (task.updatedAt && draft.savedAt && draft.savedAt <= task.updatedAt) return lists;
    if ((task.details || '') === draft.details) return lists;
    const nextList = [...list];
    nextList[idx] = { ...task, details: draft.details, updatedAt: draft.savedAt || new Date().toISOString() };
    return { ...lists, [draft.listName]: nextList };
  } catch (err) {
    return lists;
  }
}

// Battery saver defaults on for touch devices. Phones and tablets run on a
// battery and pay the real cost of backdrop blur and a full-screen gradient
// layer; a desktop plugged into the wall does not. Deliberately tests the
// pointer rather than the viewport width - a desktop browser with a narrow
// window is still a desktop, and would otherwise be opted in for no reason.
//
// Evaluated once at module load rather than inside the component, because
// DEFAULT_SETTINGS is rebuilt on every render and the answer cannot change for
// the life of the page.
const IS_TOUCH_DEVICE =
  typeof window !== 'undefined' &&
  typeof window.matchMedia === 'function' &&
  window.matchMedia('(hover: none) and (pointer: coarse)').matches;

// An internal clipboard, used only as a fallback.
//
// Pasting rich content depends on reading 'text/html' from the paste event, and
// that is not dependable - iOS Safari in particular often exposes only
// 'text/plain', which is why copying a checklist from one task to another came
// back as bare text. So a copy out of the details editor also stashes its own
// HTML here, keyed to the exact plain text the browser will carry alongside it.
//
// The text acts as the key on purpose: if the user copies something else in
// between, from any other app, the plain text won't match and the stash is
// correctly ignored rather than pasting stale content.
let internalClipboard = { text: '', html: '' };

// Font choices. `ui` is the display face (headings, tabs, buttons); `body` is
// the reading face (task text, notes). Both are named per option so a choice is
// a coherent pairing rather than two dropdowns to get wrong.
//
// `google` is the families to request, or null for the system stack - which
// costs no network at all and is the fastest possible option.
const FONT_OPTIONS = [
  {
    id: 'default', label: 'Quicksand & Nunito', note: 'The original pairing',
    ui: "'Quicksand', sans-serif", body: "'Nunito', sans-serif",
    google: 'Quicksand:wght@400;500;600;700&family=Nunito:wght@400;500;600;700'
  },
  {
    id: 'system', label: 'System', note: 'Your device\'s own font - loads instantly',
    ui: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    body: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    google: null
  },
  {
    id: 'serif', label: 'Lora & Inter', note: 'Bookish headings, plain body',
    ui: "'Lora', Georgia, serif", body: "'Inter', sans-serif",
    google: 'Lora:wght@500;600;700&family=Inter:wght@400;500;600;700'
  },
  {
    id: 'mono', label: 'Space Grotesk & Inter', note: 'Geometric and technical',
    ui: "'Space Grotesk', sans-serif", body: "'Inter', sans-serif",
    google: 'Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600;700'
  },
  {
    id: 'humanist', label: 'Nunito', note: 'One rounded face throughout',
    ui: "'Nunito', sans-serif", body: "'Nunito', sans-serif",
    google: 'Nunito:wght@400;500;600;700;800'
  }
];

// The timer's duration choices, defined once. The dropdown, the label shown on
// it and the progress ring all read from here - previously the list and a long
// ternary chain that mapped values to labels were each duplicated across two
// render sites, so adding an option meant four edits and leaving one behind
// showed a duration with no name.
const DURATION_OPTIONS = [
  { value: '', label: 'Timer' },
  { value: 300, label: '5 Minutes' },
  { value: 420, label: '7 Minutes' },
  { value: 600, label: '10 Minutes' },
  { value: 900, label: '15 Minutes' },
  { value: 1500, label: '25 Minutes' },
  { value: 1800, label: '30 Minutes' },
  { value: 3600, label: '60 Minutes' }
];

// Completion animation timing. These three numbers have to agree, and they used
// to be written out separately - a JS timer, a CSS transition-delay and a commit
// timeout - so nudging one silently desynchronised the others: the row could
// start collapsing before the tick had been seen, or the task could swap lists
// while still visibly fading.
const COMPLETE_HOLD_MS = 900;   // tick lit, nothing moving yet
const COMPLETE_ANIM_MS = 400;   // fade and collapse, run together
const COMPLETE_TOTAL_MS = COMPLETE_HOLD_MS + COMPLETE_ANIM_MS + 50;

// Moving a task between To Do and Backlog reuses the same fade-and-collapse,
// so rows below slide up into the gap instead of jumping - but with no hold.
// The 900ms above buys time to SEE the tick light up; a section move has no
// such moment, and a card that sits motionless for most of a second after a
// button press reads as the app having hung rather than as a flourish.
const MOVE_HOLD_MS = 0;

// How long the details take to slide shut. Shorter than the task exit above:
// that one has a story to tell (the tick, then the row leaving), while this is
// just a panel getting out of the way, and a slow close makes the app feel
// like it is thinking.
const DETAILS_CLOSE_MS = 220;

// Self-contained SVG marks, so they belong at module scope alongside the other
// icons. They were declared inside LittleFiresApp and referenced by Task, which
// only breaks once Task is hoisted - and only on the expanded task, since that
// is the one place they render.
// Start and end of a project or goal as one short line. Both fields are
// date-only strings, so they go through parseLocalDate - new Date() would read
// them as UTC and show the day before for anyone behind it.
function formatProjectSpan(item, parseLocalDate) {
  const fmt = (value) => {
    const d = parseLocalDate(value);
    return d ? d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : null;
  };
  const start = item && item.startDate ? fmt(item.startDate) : null;
  const end = item && item.endDate ? fmt(item.endDate) : null;
  if (start && end) return start === end ? start : start + ' – ' + end;
  return start || end || '';
}

// The element that actually scrolls around a card. On mobile that is
// .tasks-container (capped at 68vh), not the window - scrolling the window
// would move the page while the card stayed exactly where it was.
function scrollPortFor(el) {
  // Two passes, and the second one is the fix.
  //
  // Requiring scrollHeight > clientHeight looks sensible and is wrong at the
  // only moment that matters. The port is captured BEFORE a section expands -
  // when the list often does not overflow yet - so the check failed, this
  // returned null, and the caller fell back to scrolling the window. The
  // window is not what moves: the list is. So the restore quietly scrolled
  // nothing, and all that was visible on collapse was the browser clamping
  // the list, which reads exactly like a snap.
  //
  // The first pass still prefers a container that is scrolling right now,
  // which is the honest answer when there is one. The second accepts a
  // container that merely CAN scroll - it is the thing that will be scrolling
  // a moment from now, once the content it holds has grown.
  const scrollable = (node, requireOverflow) => {
    const style = window.getComputedStyle(node);
    if (!/(auto|scroll|overlay)/.test(style.overflowY)) return false;
    return requireOverflow ? node.scrollHeight > node.clientHeight : true;
  };

  for (const requireOverflow of [true, false]) {
    let node = el && el.parentElement;
    while (node && node !== document.body && node !== document.documentElement) {
      if (scrollable(node, requireOverflow)) return node;
      node = node.parentElement;
    }
  }
  return null;
}

// Reading and writing the scroll position of whatever is actually scrolling -
// an element on mobile, the window on a page that scrolls itself.
function readScrollTop(port) {
  if (port) return port.scrollTop;
  return window.scrollY || window.pageYOffset || 0;
}

function writeScrollTop(port, top, smooth) {
  const target = { top: Math.max(0, top), behavior: smooth ? 'smooth' : 'auto' };
  try {
    if (port) port.scrollTo(target); else window.scrollTo(target);
  } catch (err) {
    // Older WebKit rejects the options object.
    if (port) port.scrollTop = Math.max(0, top);
    else window.scrollTo(0, Math.max(0, top));
  }
}

// Expanding a task scrolls it into view; collapsing it should put the page back
// where it was, so opening something at the bottom of a long list does not
// leave you somewhere you never chose to be.
//
// Not unconditionally, though. If the person scrolled somewhere else while the
// task was open - reading further down, going back up to check something - then
// yanking them to a position from before is the app overruling a deliberate
// action. So the return only happens if they are still where the expand scroll
// put them.
const SCROLL_RESTORE_TOLERANCE = 48;

function shouldRestoreScroll(info, currentTop, tolerance = SCROLL_RESTORE_TOLERANCE) {
  if (!info) return false;
  // Nothing moved on expand, so there is nothing to undo.
  if (info.from == null) return false;
  // The expand scroll had not settled yet, so the person cannot have chosen a
  // position of their own - restoring is safe.
  if (info.landed == null) return true;
  return Math.abs(currentTop - info.landed) <= tolerance;
}

// Calls back once a scroll has come to rest.
//
// There is no reliable event for "the smooth scroll you asked for has
// finished": scrollend exists but is not everywhere, so it is used when present
// and a frame-by-frame check stands in when it is not. Three still frames is
// enough to be sure motion has stopped without waiting long enough to feel it.
//
// The timeout is a backstop, not the mechanism. A scroll that never starts -
// because the target was already the current position - settles in three frames
// rather than hanging until it expires.
function onScrollSettled(port, done, timeoutMs = 700) {
  const target = port || window;
  let finished = false;
  let raf = null;
  let last = readScrollTop(port);
  let stillFrames = 0;

  const cleanup = () => {
    if (raf) cancelAnimationFrame(raf);
    clearTimeout(timer);
    if (hasScrollEnd) target.removeEventListener('scrollend', finish);
  };
  const finish = () => {
    if (finished) return;
    finished = true;
    cleanup();
    done();
  };

  const hasScrollEnd = typeof window !== 'undefined' && 'onscrollend' in window;
  const timer = setTimeout(finish, timeoutMs);
  if (hasScrollEnd) target.addEventListener('scrollend', finish, { once: true });

  const tick = () => {
    const now = readScrollTop(port);
    stillFrames = Math.abs(now - last) < 0.5 ? stillFrames + 1 : 0;
    last = now;
    if (stillFrames >= 3) return finish();
    raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);
  return cleanup;
}

// Should an expanded SECTION be brought into view?
//
// Narrower than the rule for a task card, and deliberately so. A section is
// opened from a header you are already looking at, so the only thing worth
// correcting is content that has just appeared below the fold. Anything else -
// a header near the top, a section that fits - is already where you can see it,
// and moving the page then would be the app overruling a view you chose.
function sectionNeedsReveal(sectionRect, portRect, margin = EXPAND_SCROLL_MARGIN) {
  if (!sectionRect || !portRect) return false;
  // Nothing ran past the bottom, so nothing to correct.
  if (sectionRect.bottom <= portRect.bottom) return false;
  // Its header is already at the top: scrolling to it would move nothing, or
  // would nudge the page for no reason.
  if (sectionRect.top <= portRect.top + margin) return false;
  return true;
}

// Should an expanded card be brought into view, given where it sits?
//
// Only when it isn't already comfortably in the scrollport: either its top is
// above the top edge, or it runs past the bottom. A card that already fits is
// left alone - scrolling something the user can already see reads as the app
// moving on its own.
const EXPAND_SCROLL_MARGIN = 12;
function needsScrollIntoView(cardRect, portRect, margin = EXPAND_SCROLL_MARGIN) {
  if (!cardRect || !portRect) return false;
  if (cardRect.top < portRect.top + margin) return true;
  if (cardRect.bottom > portRect.bottom) return true;
  return false;
}

// ---- Calendar day grouping -------------------------------------------------
// The same three buckets the task list and the project detail already use, in
// the same order.
//
// One deliberate difference: To Do is "not completed and not backlog" rather
// than section === 'todo'. `section` is only set at creation and has never
// been backfilled, so a task old enough to predate the field has no section at
// all - and an equality test would put it in no bucket, silently dropping it
// from the day. Defining the default bucket by exclusion means every task
// lands somewhere.
const CALENDAR_STATUS_GROUPS = [
  { key: 'todo', label: 'To Do', match: (t) => !t.completed && t.section !== 'backlog' },
  { key: 'backlog', label: 'Backlog', match: (t) => !t.completed && t.section === 'backlog' },
  { key: 'complete', label: 'Complete', match: (t) => !!t.completed }
];

// How far to scroll so the caret clears the keyboard AND the task's name stays
// on screen, given that both cannot always fit.
//
// The caret alone was the old rule, and it under-specified the problem. iOS
// scrolls a focused element into view itself, and the details editor is tall,
// so focusing it scrolls far enough to fit the whole box - taking the task
// title off the top with it. You end up typing into an unlabelled panel with no
// indication of which task you are in.
//
// Returns a delta to add to scrollTop: positive scrolls down, negative up.
// Order matters. Clearing the keyboard wins outright, because not seeing what
// you type is worse than not seeing what you are typing into. Only when there
// is slack left over does it pull back to recover the title, and only by as
// much as that slack allows.
const KEYBOARD_CARET_GAP = 16;

function keyboardScrollAdjustment({ caretBottom, anchorTop, portTop, visibleBottom, gap = KEYBOARD_CARET_GAP }) {
  if (![caretBottom, portTop, visibleBottom].every(v => typeof v === 'number' && isFinite(v))) return 0;

  // The caret is behind the keys. Nothing else matters until that is fixed.
  const down = caretBottom - visibleBottom + gap;
  if (down > 0) return down;

  // Nothing to keep in view.
  if (anchorTop == null || !isFinite(anchorTop)) return 0;

  // How far the anchor sits above the top edge of the scrollport.
  const above = portTop - anchorTop;
  if (above <= 0) return 0;                       // still visible, leave it alone

  // Room between the caret and the keyboard - how far we can scroll back up
  // before the caret is covered again.
  const slack = visibleBottom - gap - caretBottom;
  if (slack <= 0) return 0;

  return -Math.min(above, slack);
}



// Where the flame band ends and the rest begins.
//
// The list is already sorted into bands and drag-to-reorder REFUSES moves
// across this boundary (see canReorderTogether) - so the line is not new
// structure, it is existing structure made visible. A refused drag currently
// has no explanation on screen; this is it.
//
// Returns the id of the last high-priority task, or null when a divider would
// say nothing: no flagged tasks, or nothing but flagged tasks. A rule pinned to
// the top or bottom of a list is just noise.
function priorityBoundaryId(tasks) {
  const list = Array.isArray(tasks) ? tasks : [];
  const flagged = list.filter(t => t && t.priority === 'high');
  if (flagged.length === 0 || flagged.length === list.length) return null;
  // Only meaningful if the bands are actually contiguous, which the display
  // sort guarantees. If something ever renders them interleaved, drawing one
  // line in the middle would be worse than drawing none.
  const lastFlaggedIndex = list.reduce(
    (acc, t, i) => (t && t.priority === 'high' ? i : acc), -1);
  const contiguous = list
    .slice(0, lastFlaggedIndex + 1)
    .every(t => t && t.priority === 'high');
  if (!contiguous) return null;
  return list[lastFlaggedIndex].id;
}

// Groups drill-down rows by list for the report panels, newest first inside each
// group. Takes { list, task } entries so the caller can hand over whatever it
// actually counted rather than a re-derived set.
//
// Order follows the caller's list order, so the panel reads down the page in the
// same order as the tabs and the legend.
function groupDrilldownByList(entries, order) {
  const byList = {};
  (entries || []).forEach(e => {
    if (!e || !e.task) return;
    (byList[e.list] = byList[e.list] || []).push(e.task);
  });
  const keys = (order || []).filter(k => byList[k] && byList[k].length);
  // Anything not in the caller's order still gets shown - a list hidden from
  // the tab row is still a list these tasks came from.
  Object.keys(byList).forEach(k => { if (!keys.includes(k)) keys.push(k); });
  return keys.map(list => ({
    list,
    tasks: byList[list].slice().sort(byMostRecentlyCompleted)
  }));
}

// Completed tasks read newest-first: what you just ticked is what you want to
// see, and everything below it is history in the order it became history.
//
// Sorted on completedAt, falling back to createdAt for anything finished before
// that field was stamped. A task with neither sinks to the bottom rather than
// floating to the top, which is what a plain date subtraction would do with an
// unparseable value.
function byMostRecentlyCompleted(a, b) {
  const when = (t) => {
    const raw = (t && t.completedAt) || (t && t.createdAt) || null;
    const ms = raw ? new Date(raw).getTime() : NaN;
    return Number.isNaN(ms) ? null : ms;
  };
  const av = when(a);
  const bv = when(b);
  if (av === null && bv === null) return 0;
  if (av === null) return 1;
  if (bv === null) return -1;
  return bv - av;
}

// Empty buckets are dropped so a day with only completed tasks doesn't render
// two empty headings above them.
function groupTasksByStatus(items, getTask) {
  return CALENDAR_STATUS_GROUPS
    .map(group => ({
      key: group.key,
      label: group.label,
      items: (items || []).filter(item => group.match(getTask(item) || {}))
    }))
    .filter(group => group.items.length > 0);
}



// ---- Editor history --------------------------------------------------------
// The editor keeps its own undo stack, because the browser's cannot see most of
// what this editor does.
//
// Only five operations here ever reached the native stack: bold, underline,
// indent/outdent on a bullet, paste, and one delete. Everything that makes this
// editor what it is - inserting a checkbox, the bullet and Next Steps buttons,
// indenting a plain line, Tab, Enter inside a checklist item, Backspace turning
// one back into text, drag-to-indent, ticking a box - mutates the DOM directly
// and is invisible to it.
//
// The failure that mattered was not "undo does nothing". The native stack still
// held the typing from before, so Cmd-Z after inserting a checkbox undid the
// SENTENCE and left the checkbox behind. That is the behaviour that teaches
// someone to stop trusting undo and start being careful instead.
//
// Snapshots of innerHTML rather than a diff. A task's notes are small, the
// stack is capped, and correctness matters far more here than bytes.

// Caret position as a count of text characters from the start of the editor.
//
// A Range cannot survive what undo does - restoring replaces every node, so any
// stored reference points at something detached. An offset survives because it
// describes the text rather than the tree. Checkboxes contribute no characters,
// so a caret sitting beside one lands at the same place either way.
function captureCaretOffset(area) {
  try {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount || !area.contains(sel.anchorNode)) return null;
    const range = sel.getRangeAt(0).cloneRange();
    range.setStart(area, 0);
    return range.toString().length;
  } catch (err) {
    return null;
  }
}

function restoreCaretOffset(area, offset) {
  if (offset == null) return;
  try {
    const walker = document.createTreeWalker(area, NodeFilter.SHOW_TEXT, null);
    let seen = 0;
    let node = walker.nextNode();
    while (node) {
      const len = node.textContent.length;
      if (seen + len >= offset) {
        const range = document.createRange();
        range.setStart(node, Math.max(0, Math.min(len, offset - seen)));
        range.collapse(true);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
        return;
      }
      seen += len;
      node = walker.nextNode();
    }
    // Past the end of the text - or no text at all. The end of the editor is
    // the closest honest answer.
    const range = document.createRange();
    range.selectNodeContents(area);
    range.collapse(false);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
  } catch (err) {
    // A caret that lands in the wrong place is a nuisance; one that throws
    // would take the undo with it.
  }
}

// Consecutive keystrokes collapse into one undo step, the way every other text
// field behaves. Long enough to group a word or a phrase, short enough that a
// pause marks a boundary.
// Draws the grouping rules between runs of checkbox lines at the same indent.
//
// AT MODULE SCOPE. It used to live inside Task, which meant the notes editor -
// a completely separate part of the tree - could not see it. A call added there
// looked correct, compiled, and would have thrown ReferenceError the first time
// anyone backspaced a bullet in a note. Pure DOM work with no component
// dependencies, so there was never a reason for it to be scoped to one editor.
function refreshListMarkers(area) {
  try {
    if (!area) return;
    const lines = Array.from(area.querySelectorAll('.checkbox-line'));
    const getIndent = (l) => parseInt(l.style.marginLeft || '0') || 0;
    // Clear existing markers first (both class and inline styles)
    lines.forEach(l => {
      l.classList.remove('has-children');
      l.classList.remove('ends-list');
      l.style.borderBottom = '';
      l.style.borderTop = '';
      // Only clear the spacing we control for markers
      if (l.style.paddingBottom === '6px') l.style.paddingBottom = '';
      if (l.style.paddingTop === '8px') l.style.paddingTop = '';
    });
    for (let i = 0; i < lines.length; i++) {
      const indent = getIndent(lines[i]);
      const nextIndent = i + 1 < lines.length ? getIndent(lines[i + 1]) : -1;
      const prevIndent = i > 0 ? getIndent(lines[i - 1]) : -1;
      // "Directly under" means adjacent in the document, not merely the next
      // checkbox line. This list is built from querySelectorAll, so anything
      // that is not a checkbox line - an empty line most of all - is
      // invisible to it, and a line separated from an indented line by a
      // blank one was still being drawn as its heading.
      const childIsAdjacent = i + 1 < lines.length &&
        lines[i].nextElementSibling === lines[i + 1];
      // Parent: a line immediately followed by a more-indented line, with text
      if (nextIndent > indent && childIsAdjacent) {
        const txt = (lines[i].textContent || '').replace(/\u00A0/g, '').trim();
        if (txt) {
          // Class only. These used to also set fontWeight, borderBottom and
          // paddingBottom inline, with a comment claiming that was what made
          // the styling survive a save - but the sanitizer strips the style
          // attribute, so those three lines never once did anything. The
          // .has-children CSS is what actually renders it.
          lines[i].classList.add('has-children');
        }
      } else {
        // Not a parent anymore - remove any leftover bold from inline styles
        lines[i].style.fontWeight = '';
        const sp = lines[i].querySelector('span');
        if (sp) sp.style.fontWeight = '';
      }
      // End-of-list boundary: a top-level line that comes right after a
      // more-indented (child) line - i.e. indentation stepped back to 0.
      if (indent === 0 && prevIndent > 0) {
        lines[i].classList.add('ends-list');
        lines[i].style.borderTop = '2px solid rgba(var(--accent-rgb), 0.55)';
        lines[i].style.paddingTop = '8px';
      }
    }
  } catch (err) {
    console.error('refreshListMarkers error:', err);
  }
}

const HISTORY_COALESCE_MS = 600;
const HISTORY_LIMIT = 60;

// ---- Indent helpers --------------------------------------------------------
// Indentation is represented two different ways, and both already existed
// before the toolbar buttons did - the drag gesture and the Tab key use this
// same split, so the buttons must too or the two would disagree about what an
// indented line is.
//
//   bullets      - structural nesting (<ul> inside <li>). A bullet's depth has
//                  to be real nesting or the markers all render at one level.
//   everything   - marginLeft in fixed steps, on the line element itself
//   else           (.checkbox-line, or a plain block).
//
// execCommand('indent') is used ONLY for bullets. On a non-list block some
// browsers implement it by wrapping the line in <blockquote>, which the
// sanitizer unwraps on save - the indent would appear to work and then vanish
// when the task was reopened.
const EDITOR_INDENT_STEP = 20;

// The block the caret sits in, and how its indent is expressed.
function indentTargetAt(area, node) {
  if (!area || !node) return null;
  const el = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
  if (!el || !area.contains(el)) return null;
  const li = el.closest ? el.closest('li') : null;
  if (li && area.contains(li)) return { kind: 'bullet', line: li };
  let line = el;
  while (line && line.parentElement !== area && line !== area) line = line.parentElement;
  if (!line || line === area) return null;
  return { kind: 'block', line };
}

function blockIndent(line) {
  return parseInt((line && line.style && line.style.marginLeft) || '0') || 0;
}

// A bullet is outdentable when it sits inside a nested list, i.e. its list has
// a list ancestor still inside the editor.
function bulletIsNested(area, li) {
  const list = li && li.parentElement;
  if (!list) return false;
  const parent = list.parentElement;
  return !!(parent && area.contains(parent) && parent.closest &&
    parent.closest('ul, ol') && parent.closest('ul, ol') !== list);
}

// Text typed into an empty editor has no wrapping block - browsers leave it as
// bare text nodes until the first Enter. That is the FIRST line of most tasks,
// and indentTargetAt walks up to a direct child of the editor, so it found
// nothing there and the line simply could not be indented. Wrapping the run
// around the caret makes it an ordinary line. Mirrors the Box button, which
// had to solve exactly this for the same reason.
function wrapBareLineAt(area, node) {
  if (!area || !node) return null;
  let n = node;
  if (n === area) n = area.childNodes[0] || null;
  while (n && n.parentElement !== area) n = n.parentElement;
  if (!n) return null;
  const isBoundary = (x) => !x || (x.nodeType === Node.ELEMENT_NODE &&
    ['BR', 'DIV', 'P', 'UL', 'OL'].includes(x.tagName));
  if (isBoundary(n)) return null;
  let first = n, last = n;
  while (first.previousSibling && !isBoundary(first.previousSibling)) first = first.previousSibling;
  while (last.nextSibling && !isBoundary(last.nextSibling)) last = last.nextSibling;
  const wrapper = document.createElement('div');
  area.insertBefore(wrapper, first);
  let cur = first;
  while (cur) {
    const next = (cur === last) ? null : cur.nextSibling;
    wrapper.appendChild(cur);
    cur = next;
  }
  return wrapper;
}

// What indent/outdent should act on, wrapping a bare line first if that is
// what the caret is sitting in. Shared by the toolbar buttons and the Tab key
// so the two can never disagree about what a line is.
// Shows or hides a note's outdent button, based on whether there is anything
// to outdent - the same rule the task editor applies.
//
// The task editor drives that from React state. Notes are rendered from a map,
// so per-note state would mean a map of booleans keyed by note id, recomputed
// on every caret move, to control one button. This toggles a class on the
// button instead: the editor's own DOM already holds the answer, and reading it
// is cheaper than mirroring it.
function refreshNoteOutdentVisibility(area) {
  if (!area) return false;
  const entry = area.closest ? area.closest('.note-entry') : null;
  const button = entry ? entry.querySelector('.note-outdent-btn') : null;
  if (!button) return false;

  let atCaret = false;
  const sel = window.getSelection();
  if (sel && sel.rangeCount) {
    const node = sel.getRangeAt(0).startContainer;
    const el = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
    if (el && area.contains(el)) atCaret = canOutdentAt(area, node);
  }
  // Either the caret is somewhere outdentable, or the note has indentation
  // elsewhere - so reopening a note that was saved indented shows the button
  // without needing the caret placed first.
  const show = atCaret || hasAnyIndent(area);
  button.classList.toggle('is-hidden', !show);
  return show;
}

function resolveIndentTarget(area, node) {
  const found = indentTargetAt(area, node);
  if (found) return found;
  const wrapped = wrapBareLineAt(area, node);
  return wrapped ? { kind: 'block', line: wrapped } : null;
}

// Can the line at the caret be outdented right now?
function canOutdentAt(area, node) {
  const target = indentTargetAt(area, node);
  if (!target) return false;
  return target.kind === 'bullet'
    ? bulletIsNested(area, target.line)
    : blockIndent(target.line) > 0;
}

// Does the editor contain any indented content at all? The outdent button
// appears for either reason - the caret sitting on an indented line, or the
// document simply having indented content somewhere.
function hasAnyIndent(area) {
  if (!area) return false;
  const blocks = area.querySelectorAll('[style*="margin-left"]');
  for (const el of blocks) if (blockIndent(el) > 0) return true;
  return !!area.querySelector('ul ul, ul ol, ol ul, ol ol, li ul, li ol');
}

